// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract DIDRegistry {
    struct DIDDoc {
        address owner;
        bytes32 ipfsHash;
        bool active;
        uint256 createdAt;
        uint256 updatedAt;
    }

    mapping(bytes32 => DIDDoc) public dids;
    mapping(address => bytes32[]) public ownerDIDs;

    event DIDRegistered(bytes32 indexed didHash, address indexed owner, bytes32 ipfsHash);
    event DIDUpdated(bytes32 indexed didHash, bytes32 ipfsHash);
    event DIDDeactivated(bytes32 indexed didHash);

    function register(bytes32 _didHash, bytes32 _ipfsHash) external {
        require(!dids[_didHash].active, 'DID already registered');
        dids[_didHash] = DIDDoc({
            owner: msg.sender,
            ipfsHash: _ipfsHash,
            active: true,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });
        ownerDIDs[msg.sender].push(_didHash);
        emit DIDRegistered(_didHash, msg.sender, _ipfsHash);
    }

    function resolve(bytes32 _didHash) external view returns (DIDDoc memory) {
        return dids[_didHash];
    }

    function update(bytes32 _didHash, bytes32 _ipfsHash) external {
        require(dids[_didHash].active, 'DID not found');
        require(dids[_didHash].owner == msg.sender, 'Not the owner');
        dids[_didHash].ipfsHash = _ipfsHash;
        dids[_didHash].updatedAt = block.timestamp;
        emit DIDUpdated(_didHash, _ipfsHash);
    }

    function deactivate(bytes32 _didHash) external {
        require(dids[_didHash].active, 'DID not found');
        require(dids[_didHash].owner == msg.sender, 'Not the owner');
        dids[_didHash].active = false;
        emit DIDDeactivated(_didHash);
    }

    function getOwnerDIDs(address _owner) external view returns (bytes32[] memory) {
        return ownerDIDs[_owner];
    }
}

contracts/NSSRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract NSSRegistry {
    struct Skill {
        bytes32 publisherDidHash;
        bytes32 descriptorIpfsHash;
        uint256 priceWei;
        uint256 callCount;
        bool active;
        uint256 createdAt;
    }

    mapping(bytes32 => Skill) public skills;

    event SkillPublished(bytes32 indexed skillId, bytes32 publisherDidHash, bytes32 descriptorIpfsHash, uint256 priceWei);
    event SkillInvoked(bytes32 indexed skillId);
    event SkillDeactivated(bytes32 indexed skillId);

    function publish(bytes32 _skillId, bytes32 _publisherDidHash, bytes32 _descriptorIpfsHash, uint256 _priceWei) external {
        require(!skills[_skillId].active, 'Skill already published');
        skills[_skillId] = Skill({
            publisherDidHash: _publisherDidHash,
            descriptorIpfsHash: _descriptorIpfsHash,
            priceWei: _priceWei,
            callCount: 0,
            active: true,
            createdAt: block.timestamp
        });
        emit SkillPublished(_skillId, _publisherDidHash, _descriptorIpfsHash, _priceWei);
    }

    function invoke(bytes32 _skillId) external {
        require(skills[_skillId].active, 'Skill not found');
        skills[_skillId].callCount += 1;
        emit SkillInvoked(_skillId);
    }

    function resolve(bytes32 _skillId) external view returns (Skill memory) {
        return skills[_skillId];
    }

    function deactivate(bytes32 _skillId) external {
        require(skills[_skillId].active, 'Skill not found');
        skills[_skillId].active = false;
        emit SkillDeactivated(_skillId);
    }
}

